-- ----------------------------
-- Table structure for diet_history
-- ----------------------------
DROP TABLE IF EXISTS `diet_history`;
CREATE TABLE `diet_history`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '饮食记录主键ID，自增',
  `user_id` int NULL DEFAULT NULL COMMENT '用户ID，外键，关联的是用户表',
  `recipe_id` int NULL DEFAULT NULL COMMENT '食谱ID，外键，关联的是食谱表',
  `detail` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '备注',
  `value` double NULL DEFAULT NULL COMMENT '摄入值，单位是g',
  `create_time` datetime NULL DEFAULT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '饮食记录表' ROW_FORMAT = DYNAMIC;

