-- ----------------------------
-- Table structure for recipe
-- ----------------------------
DROP TABLE IF EXISTS `recipe`;
CREATE TABLE `recipe`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '食谱表主键ID，自增',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '食谱名',
  `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '封面',
  `type_id` int NULL DEFAULT NULL COMMENT '食谱类别ID，外键，通过后端枚举类进行管理',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '内容',
  `user_id` int NULL DEFAULT NULL COMMENT '用户ID，外键，关联的是用户表',
  `is_public` tinyint(1) NULL DEFAULT NULL COMMENT '是否是公开食谱，如果是公开食谱，需要管理员审核，私人食谱就是能自己用',
  `is_audit` tinyint(1) NULL DEFAULT NULL COMMENT '是否已经审核',
  `create_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '食谱信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of recipe
-- ----------------------------
INSERT INTO `recipe` VALUES (2, '公开食谱测试（辣子鸡）', '/api/v1.0/self-health-api/file/getFile?fileName=1754117540498Snipaste_2025-04-21_16-57-23.png', 1, '<h1 style=\"text-align: start;\">家常辣子鸡制作步骤</h1><ol><li style=\"text-align: start;\">食材准备：鸡腿肉 500 克切成 2 厘米见方的小块，用 1 勺料酒、少许盐、白胡椒粉抓匀，再加 1 勺淀粉腌制 20 分钟；干辣椒剪成段（根据嗜辣程度调整），生姜切片，大蒜切末，葱切段，准备适量花椒、白芝麻。</li><li style=\"text-align: start;\">炸制鸡肉：锅中倒油烧至六成热（筷子插入有细小气泡），放入鸡块炸至表面微黄后捞出；待油温升至八成热，复炸 1 分钟至金黄酥脆，捞出控油备用。</li><li style=\"text-align: start;\">炒香配料：锅中留少许底油，放入姜片、蒜末、葱段爆香，加入花椒和干辣椒段炒出辣味（注意小火避免炒糊），可加 1 勺豆瓣酱增加风味。</li><li style=\"text-align: start;\">翻炒入味：倒入炸好的鸡块，大火快速翻炒 2 分钟，让辣椒和花椒的香味裹满鸡肉，加少许生抽调味，最后撒上白芝麻和葱花翻炒均匀即可出锅。<br></li><li style=\"text-align: start;\">小贴士：喜欢口感更丰富可加少许花生米，鸡肉复炸能保证外酥里嫩，辣椒和花椒用量可根据接受度调整，搭配米饭风味更佳。</li></ol>', 62, 1, 1, '2025-08-02 14:52:36');
INSERT INTO `recipe` VALUES (5, '凉拌皮蛋', '/api/v1.0/self-health-api/file/getFile?fileName=1754381783662Snipaste_2025-08-05_16-14-54.png', 1, '<h1 style=\"text-align: start;\">家常辣子鸡制作步骤</h1><ol><li style=\"text-align: start;\">食材准备：鸡腿肉 500 克切成 2 厘米见方的小块，用 1 勺料酒、少许盐、白胡椒粉抓匀，再加 1 勺淀粉腌制 20 分钟；干辣椒剪成段（根据嗜辣程度调整），生姜切片，大蒜切末，葱切段，准备适量花椒、白芝麻。</li><li style=\"text-align: start;\">炸制鸡肉：锅中倒油烧至六成热（筷子插入有细小气泡），放入鸡块炸至表面微黄后捞出；待油温升至八成热，复炸 1 分钟至金黄酥脆，捞出控油备用。</li><li style=\"text-align: start;\">炒香配料：锅中留少许底油，放入姜片、蒜末、葱段爆香，加入花椒和干辣椒段炒出辣味（注意小火避免炒糊），可加 1 勺豆瓣酱增加风味。</li><li style=\"text-align: start;\">翻炒入味：倒入炸好的鸡块，大火快速翻炒 2 分钟，让辣椒和花椒的香味裹满鸡肉，加少许生抽调味，最后撒上白芝麻和葱花翻炒均匀即可出锅。</li><li style=\"text-align: start;\">小贴士：喜欢口感更丰富可加少许花生米，鸡肉复炸能保证外酥里嫩，辣椒和花椒用量可根据接受度调整，搭配米饭风味更佳。</li></ol><p style=\"text-align: start;\"><br></p>', 62, 1, 1, '2025-08-05 16:17:30');
