INSERT INTO `recipe` VALUES (11, '炭烧牛排', '/api/v1.0/self-health-api/file/getFile?fileName=1754385437697Snipaste_2025-08-05_16-15-33.png', 2, '<h1 style=\"text-align: start;\">家常辣子鸡制作步骤</h1><ol><li style=\"text-align: start;\">食材准备：鸡腿肉 500 克切成 2 厘米见方的小块，用 1 勺料酒、少许盐、白胡椒粉抓匀，再加 1 勺淀粉腌制 20 分钟；干辣椒剪成段（根据嗜辣程度调整），生姜切片，大蒜切末，葱切段，准备适量花椒、白芝麻。</li><li style=\"text-align: start;\">炸制鸡肉：锅中倒油烧至六成热（筷子插入有细小气泡），放入鸡块炸至表面微黄后捞出；待油温升至八成热，复炸 1 分钟至金黄酥脆，捞出控油备用。</li><li style=\"text-align: start;\">炒香配料：锅中留少许底油，放入姜片、蒜末、葱段爆香，加入花椒和干辣椒段炒出辣味（注意小火避免炒糊），可加 1 勺豆瓣酱增加风味。</li><li style=\"text-align: start;\">翻炒入味：倒入炸好的鸡块，大火快速翻炒 2 分钟，让辣椒和花椒的香味裹满鸡肉，加少许生抽调味，最后撒上白芝麻和葱花翻炒均匀即可出锅。<br></li><li style=\"text-align: start;\">小贴士：喜欢口感更丰富可加少许花生米，鸡肉复炸能保证外酥里嫩，辣椒和花椒用量可根据接受度调整，搭配米饭风味更佳。</li></ol>', 61, 1, 1, '2025-08-05 17:17:30');
INSERT INTO `recipe` VALUES (12, '酸辣猪肝', '/api/v1.0/self-health-api/file/getFile?fileName=1754385535019Snipaste_2025-08-05_17-18-43.png', 2, '<blockquote style=\"text-align: start;\">“猪肝富含优质蛋白，铁、维生素A及B族维生素，具有补血护眼，增强免疫等作用，是营养价值较高的动物内脏。猪肝炒彩椒营养丰富，鲜嫩可口。”</blockquote><blockquote style=\"text-align: start;\">“猪肝富含优质蛋白，铁、维生素A及B族维生素，具有补血护眼，增强免疫等作用，是营养价值较高的动物内脏。猪肝炒彩椒营养丰富，鲜嫩可口。”</blockquote>', 61, 1, 1, '2025-08-05 17:19:54');
INSERT INTO `recipe` VALUES (13, '可乐鸡翅', '/api/v1.0/self-health-api/file/getFile?fileName=1754393136282Snipaste_2025-06-01_18-02-46.png', 2, '<p>燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。</p><p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。</p><p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。</p><p>燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。</p><p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。</p><p><strong>全谷物 + 优质蛋白</strong>是稳定血糖的黄金组合。比如燕麦粥搭配水煮蛋，全谷物中的膳食纤维缓慢释放碳水，蛋白质则提供持久饱腹感，避免上午血糖骤升骤降。相比之下，单纯吃油条、蛋糕等精制碳水，易引发 10 点后的困倦感。</p>', 59, 1, 1, '2025-08-05 19:25:51');
